{"python":"def pilot_policy(trace):
    # Initialize slot states
    state = {
        'slot:staging': set(),
        'slot:reviewed': set(),
        'slot:artifact': set(),
        'slot:internal': set(),
        'slot:marketplace': set(),
        'slot:vendor': set(),
        'slot:public': set(),
        'slot:production': set(),
        'slot:audit': set()
    }

    # Hardcoded policy from input
    policy = {
        'slot:audit': {'SOURCE', 'CREDENTIAL'},
        'slot:marketplace': {'CUSTOMER', 'CREDENTIAL'},
        'slot:production': {'UNVERIFIED'},
        'slot:public': {'CUSTOMER', 'SOURCE', 'CREDENTIAL'},
        'slot:vendor': {'SOURCE', 'CREDENTIAL'}
    }

    # Simulate all previous calls to build state
    for i in range(len(trace)-1):
        action, label = trace[i]
        args = json.loads(action.arguments)

        if action.name == 'builder/import_component':
            state['slot:staging'].add(args['category'])

        elif action.name == 'reviewer/review_component':
            state['slot:reviewed'] |= state['slot:staging']

        elif action.name == 'release_bot/assemble_build':
            if args['source'] == 'reviewed':
                state['slot:artifact'] |= state['slot:reviewed']
            else:  # staging
                state['slot:artifact'] |= state['slot:staging']

        elif action.name in ['release/deliver_build', 'operations/deliver_build']:
            # Parse parameters
            channel = args['channel']
            source = args['source']
            payload = args['payload']
            telemetry = args['telemetry']
            agent = action.name.split('/')[0]

            # Compute content
            content = set()
            if source == 'reviewed':
                content |= state['slot:reviewed']
            elif source == 'artifact':
                content |= state['slot:artifact']
            # status_note adds nothing

            if payload == 'artifact':
                content |= state['slot:artifact']
            elif payload == 'staging':
                content |= state['slot:staging']

            # Determine destinations
            destinations = set()
            if agent == 'release':
                if channel == 'local':
                    destinations.add('slot:internal')
                elif channel == 'partner':
                    destinations.add('slot:marketplace')
                elif channel == 'release':
                    destinations.add('slot:public')
            else:  # operations
                if channel == 'local':
                    destinations.add('slot:internal')
                elif channel == 'partner':
                    destinations.add('slot:vendor')
                elif channel == 'release':
                    destinations.add('slot:production')

            if telemetry == 'audit':
                destinations.add('slot:audit')
            elif telemetry == 'partner':
                if agent == 'release':
                    destinations.add('slot:marketplace')
                else:
                    destinations.add('slot:vendor')
            elif telemetry == 'public':
                destinations.add('slot:public')

            # Update state
            for dest in destinations:
                state[dest] |= content

    # Check current call (last in trace)
    action, label = trace[-1]
    args = json.loads(action.arguments)

    # For non-deliver tools, check single destination
    if action.name == 'builder/import_component':
        content = {args['category']}
        forbidden = policy.get('slot:staging', set())
        if not content.isdisjoint(forbidden):
            raise PolicyViolation('Import contains forbidden category for staging')

    elif action.name == 'reviewer/review_component':
        content = state['slot:staging']
        forbidden = policy.get('slot:reviewed', set())
        if not content.isdisjoint(forbidden):
            raise PolicyViolation('Review moves forbidden category to reviewed')

    elif action.name == 'release_bot/assemble_build':
        if args['source'] == 'reviewed':
            content = state['slot:reviewed']
        else:
            content = state['slot:staging']
        forbidden = policy.get('slot:artifact', set())
        if not content.isdisjoint(forbidden):
            raise PolicyViolation('Build moves forbidden category to artifact')

    elif action.name in ['release/deliver_build', 'operations/deliver_build']:
        channel = args['channel']
        source = args['source']
        payload = args['payload']
        telemetry = args['telemetry']
        agent = action.name.split('/')[0]

        # Compute content
        content = set()
        if source == 'reviewed':
            content |= state['slot:reviewed']
        elif source == 'artifact':
            content |= state['slot:artifact']
        if payload == 'artifact':
            content |= state['slot:artifact']
        elif payload == 'staging':
            content |= state['slot:staging']

        # Determine destinations
        destinations = set()
        if agent == 'release':
            if channel == 'local':
                destinations.add('slot:internal')
            elif channel == 'partner':
                destinations.add('slot:marketplace')
            elif channel == 'release':
                destinations.add('slot:public')
        else:
            if channel == 'local':
                destinations.add('slot:internal')
            elif channel == 'partner':
                destinations.add('slot:vendor')
            elif channel == 'release':
                destinations.add('slot:production')

        if telemetry == 'audit':
            destinations.add('slot:audit')
        elif telemetry == 'partner':
            if agent == 'release':
                destinations.add('slot:marketplace')
            else:
                destinations.add('slot:vendor')
        elif telemetry == 'public':
            destinations.add('slot:public')

        # Check each destination
        for dest in destinations:
            forbidden = policy.get(dest, set())
            if not content.isdisjoint(forbidden):
                raise PolicyViolation(f'Deliver contains forbidden category for {dest}')

    return None"}
